    let plugin = tree
        .plugins
        .get(&normalized)
        .or_else(|| tree.plugins.get(plugin_name));

300→    let plugin = match plugin {
        Some(p) => p,
        None => bail!(
            "Plugin '{}' not found. Run 'dbus-plugin-cli list' to see available plugins.",
            plugin_name
