            .unwrap_or_else(|_| SESSION_BUS_SOCK.to_string());
        zbus::connection::Builder::address(addr.as_str())
            .context("Invalid bus address")?
            .build()
            .await
            .context("Failed to connect to opdbus session bus at /run/opdbus/session-bus.sock")
    }
